import re

def extract_amounts(text):
    if not text:
        return []
    # simple patterns: $123.45 or 123.45
    return re.findall(r'\$\s*([0-9]+(?:\.[0-9]{1,2})?)', text)

edwin_msgs_sorted = sorted(edwin_msgs, key=lambda x: x['sent_at'])
print('Edwin msgs count', len(edwin_msgs_sorted))

for m in edwin_msgs_sorted:
    msg = m.get('message','')
    amts = extract_amounts(msg)
    if amts or any(k.lower() in msg.lower() for k in ['cost','total','amazon','order','defective','return','venmo','e310','vitamix','blender']):
        print('---', m['sent_at'])
        print(m['sender']['name'], '->', m['receiver']['name'])
        print(msg)
        if amts:
            print('amounts:', amts)

